package com.learnagent.analysis;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.learnagent.quiz.*;import com.learnagent.task.*;import java.util.*;import org.junit.jupiter.api.*;
class AnalysisServiceTest{private AnswerRecord record(boolean ok){return new AnswerRecord(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"Linux permissions",ok?"A":"B",ok);}@Test void ignores_single_wrong_attempt(){var repo=mock(AnswerRecordRepository.class);when(repo.findAll()).thenReturn(List.of(record(false)));assertThat(service(repo).weakPoints(null)).isEmpty();}@Test void identifies_low_accuracy_after_minimum_attempts(){var repo=mock(AnswerRecordRepository.class);when(repo.findAll()).thenReturn(List.of(record(true),record(true),record(false),record(false),record(false)));assertThat(service(repo).weakPoints(null)).singleElement().satisfies(x->assertThat(x.accuracy()).isEqualTo(.4));}@Test void ignores_good_accuracy(){var repo=mock(AnswerRecordRepository.class);when(repo.findAll()).thenReturn(List.of(record(true),record(true),record(true),record(true),record(false)));assertThat(service(repo).weakPoints(null)).isEmpty();}private AnalysisService service(AnswerRecordRepository a){return new AnalysisService(a,mock(QuizRepository.class),mock(StudyTaskRepository.class),new AnalysisProperties(3,.6));}}
